import static org.junit.Assert.*;

public class TokenBuffer_writeNumber_TriageGen2Test {

    private ObjectMapper mapper;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        tokenBuffer = new TokenBuffer(mapper);
    }







    @Test
    public void testWriteNumber_Infinity() throws IOException {
        float value = Float.POSITIVE_INFINITY;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        // Jackson typically handles Infinity as a specific token or value
        Assert.assertEquals(Float.POSITIVE_INFINITY, parser.getFloatValue());
    }








}

